import { Accessor, createContext, createMemo, useContext } from "solid-js";

import { DatabaseCache } from "#core/ui/utilities/utilities-data.js";
import { CivInfo, CivSelectModel } from "#core/ui-next/screens/create-game/civ-select-model.js";
import { LeaderInfo, LeaderSelectModel } from "#core/ui-next/screens/create-game/leader-select-model.js";
import { ModelLifecycle, ModelRegistry } from "#core/ui-next/services/model-registry.js";

export interface LeaderBiasInfo {
	leaderId: string;
	choice: string | undefined;
	reason: string | undefined;
	bias: number;
}

export interface CivBiasInfo {
	civId: string;
	choice: string | undefined;
	reason: string | undefined;
	bias: number;
}

export interface RecommendedChoiceInfo {
	forCiv: Accessor<Map<string, LeaderBiasInfo>>;
	forLeader: Accessor<Map<string, CivBiasInfo>>;

	historicalLeaders: Accessor<LeaderInfo[]>;
	historicalCivs: Accessor<CivInfo[]>;

	recommendedLeaders: Accessor<LeaderInfo[]>;
	recommendedCivs: Accessor<CivInfo[]>;

	unrecommendedLeaders: Accessor<LeaderInfo[]>;
	unrecommendedCivs: Accessor<CivInfo[]>;
}

function createRecommendedChoiceModel(): RecommendedChoiceInfo {
	const dbCache = new DatabaseCache("config");
	const leaderCivBiasData = dbCache
		.query("select * from LeaderCivilizationBias")
		.filter((row) => (row.ReasonType as string) != "LOC_REASON_LIVE_EVENT_DESCRIPTION");

	const civModel = CivSelectModel.get();
	const leaderModel = LeaderSelectModel.get();
	const hightlightBiasThreshold = 2; // Bias must be greater than this value to be hightlighted.

	const leadersForCiv = createMemo(() => {
		const civ = civModel.selectedCiv();
		const leaderMap = new Map<string, LeaderBiasInfo>();

		if (!civ) {
			return leaderMap;
		}

		const leaders = leaderCivBiasData.filter((row) => row.CivilizationType == civ.civID);
		for (const leader of leaders) {
			const info = {
				leaderId: leader.LeaderType as string,
				choice: leader.ChoiceType as string | undefined,
				reason: leader.ReasonType as string | undefined,
				bias: leader.Bias as number | 0,
			};
			leaderMap.set(leader.LeaderType as string, info);
		}

		return leaderMap;
	});

	const civsForLeader = createMemo(() => {
		const leader = leaderModel.selectedLeader();
		const civs = leaderCivBiasData.filter((row) => row.LeaderType == leader.leaderID);
		const civMap = new Map<string, CivBiasInfo>();

		for (const civ of civs) {
			const info = {
				civId: civ.CivilizationType as string,
				choice: civ.ChoiceType as string | undefined,
				reason: civ.ReasonType as string | undefined,
				bias: civ.Bias as number | 0,
			};
			civMap.set(civ.CivilizationType as string, info);
		}

		return civMap;
	});

	const historicalLeaders = createMemo(() => {
		const leaders = leadersForCiv();
		return leaderModel.leaders.filter(
			(l) => leaders.get(l.leaderID)?.choice == "LOC_CREATE_GAME_HISTORICAL_CHOICE",
		);
	});

	const historicalCivs = createMemo(() => {
		const civs = civsForLeader();
		let maxBias = Number.NEGATIVE_INFINITY;
		for (const [_, civ] of civs) {
			const bias = civ.bias as number | 0;
			if (bias > maxBias) {
				maxBias = bias;
			}
		}

		return civModel.civs.filter(
			(c) =>
				civs.has(c.civID) &&
				(civs.get(c.civID)?.bias ?? 0) > hightlightBiasThreshold &&
				civs.get(c.civID)?.bias == maxBias,
		);
	});

	const recommendedLeaders = createMemo(() => {
		const leaders = leadersForCiv();
		return leaderModel.leaders.filter(
			(l) => leaders.has(l.leaderID) && leaders.get(l.leaderID)?.choice != "LOC_CREATE_GAME_HISTORICAL_CHOICE",
		);
	});

	const recommendedCivs = createMemo(() => {
		const civs = civsForLeader();
		let maxBias = Number.NEGATIVE_INFINITY;
		for (const [_, civ] of civs) {
			const bias = civ.bias as number | 0;
			if (bias > maxBias) {
				maxBias = bias;
			}
		}

		return civModel.civs.filter(
			(c) =>
				civs.has(c.civID) &&
				((civs.get(c.civID)?.bias ?? 0) <= hightlightBiasThreshold || civs.get(c.civID)?.bias != maxBias),
		);
	});

	const unrecommendedLeaders = createMemo(() => {
		const leaders = leadersForCiv();
		return leaderModel.leaders.filter((l) => !leaders.has(l.leaderID));
	});

	const unrecommendedCivs = createMemo(() => {
		const civs = civsForLeader();
		return civModel.civs.filter((c) => !civs.has(c.civID));
	});

	return {
		forCiv: leadersForCiv,
		forLeader: civsForLeader,
		historicalCivs,
		historicalLeaders,
		recommendedCivs,
		recommendedLeaders,
		unrecommendedCivs,
		unrecommendedLeaders,
	};
}

export const RecommendedChoiceModel = ModelRegistry.register(
	"RecommendedChoiceModel",
	ModelLifecycle.SharedInstance,
	createRecommendedChoiceModel,
);

export const RecommendedChoiceModelContext = createContext<RecommendedChoiceInfo>();

export function useRecommendedChoiceModelContext() {
	const context = useContext(RecommendedChoiceModelContext);

	if (!context) {
		throw new Error("useRecommendedChoiceModel: Cannot find context!");
	}

	return context;
}
